fn decode_movsr_hint_imm(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xfb00000 != 0x3200000 {
        return Err(DecodeError::Unallocated);
    }
    // cond=xxxx|00|1|10|R=x|10|imm4=xxxx|xxxx|imm12=xxxxxxxxxxxx
    match (
        bits & 0xff,
        ((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf,
        bits & 0xf0,
    ) {
        (0, 0, _) => {
            // NOP
            // NOP{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let unpredictable: bool = imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::NopA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (1, 0, _) => {
            // YIELD
            // YIELD{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let unpredictable: bool = imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::YieldA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (2, 0, _) => {
            // WFE
            // WFE{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let unpredictable: bool = imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::WfeA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (3, 0, _) => {
            // WFI
            // WFI{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let unpredictable: bool = imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::WfiA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (4, 0, _) => {
            // SEV
            // SEV{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let unpredictable: bool = imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::SevA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (5, 0, _) => {
            // SEVL
            // SEVL{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let unpredictable: bool = imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::SevlA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (16, 0, _) => {
            // ESB
            // ESB{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let cond: u8 = (bits >> 28) as u8;
            let unpredictable: bool =
                imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000 || cond != 0b1110;
            Ok(Instruction::EsbA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (18, 0, _) => {
            // TSB
            // TSB{<c>}{<q>}  CSYNC
            let imm12: u16 = (bits & 0xfff) as u16;
            let cond: u8 = (bits >> 28) as u8;
            let unpredictable: bool =
                imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000 || cond != 0b1110;
            Ok(Instruction::TsbA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (20, 0, _) => {
            // CSDB
            // CSDB{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let cond: u8 = (bits >> 28) as u8;
            let unpredictable: bool =
                imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000 || cond != 0b1110;
            Ok(Instruction::CsdbA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (22, 0, _) => {
            // CLRBHB
            // CLRBHB{<c>}{<q>}
            let imm12: u16 = (bits & 0xfff) as u16;
            let unpredictable: bool = imm12 >> 8 != 0b0000 || bits & 0xf000 != 0xf000;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::ClrbhbA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        (_, 0, 240) => {
            // DBG
            // DBG{<c>}{<q>}  #<option>
            let unpredictable: bool = bits & 0xff00 != 0xf000;
            let cond: u8 = (bits >> 28) as u8;
            let option: u8 = (bits & 0xf) as u8;
            Ok(Instruction::DbgA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                option,
                unpredictable,
            })
        }
        (_, _, _) if (((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) != 0 => {
            // MSR (immediate)
            // MSR{<c>}{<q>}  <spec_reg>, #<imm>
            let R: u8 = ((bits >> 22) & 0x1) as u8;
            let mask: u8 = ((bits >> 16) & 0xf) as u8;
            if mask == 0b0000 && R == 0b0 {
                return Err(DecodeError::UNDEF);
            }
            let imm12: u16 = (bits & 0xfff) as u16;
            let imm32: u32 = shared::A32ExpandImm(imm12);
            let unpredictable: bool = bits & 0xf000 != 0xf000 || mask == 0b0000;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::MsrIA1As {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                spec_reg: R << 4 | mask,
                imm: imm32,
                unpredictable,
            })
        }
        _ => {
            if (((bits & 0x70) == 80) && ((((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) == 0))
                || (((bits & 0xa0) == 32)
                    && ((((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) == 0))
                || (((bits & 0xe8) == 8) && ((((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) == 0))
                || (((bits & 0xfe) == 6) && ((((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) == 0))
                || (((bits & 0xf9) == 17)
                    && ((((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) == 0))
                || (((bits & 0xf0) == 64)
                    && ((((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) == 0))
                || (((bits & 0xc0) == 128)
                    && ((((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) == 0))
                || (((bits & 0xd0) == 192)
                    && ((((bits >> 22) & 0x1) << 4 | (bits >> 16) & 0xf) == 0))
            {
                Err(DecodeError::ReservedHint)
            } else {
                Err(DecodeError::Unallocated)
            }
        }
    }
}

fn decode_movsr_reg(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xf9000f0 != 0x1000000 {
        return Err(DecodeError::Unallocated);
    }
    // cond=xxxx|00|010|R=x|x|0|mask=xxxx|Rd=xxxx|xx|B=x|m=x|0|000|Rn=xxxx
    match bits & 0x200200 {
        0 => {
            // MRS
            // MRS{<c>}{<q>}  <Rd>, <spec_reg>
            let mask: u8 = ((bits >> 16) & 0xf) as u8;
            let m: u8 = ((bits >> 8) & 0x1) as u8;
            let Rn: u8 = (bits & 0xf) as u8;
            let Rd: u8 = ((bits >> 12) & 0xf) as u8;
            let R: u8 = ((bits >> 22) & 0x1) as u8;
            let unpredictable: bool =
                mask != 0b1111 || m != 0b0 || Rn != 0b0000 || bits & 0xc00 != 0x0 || Rd == 15;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::MrsA1As {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                spec_reg: match SpecReg_Apsr_Spsr::from_bits(R) {
                    Some(symbol) => symbol,
                    None => return Err(DecodeError::Unallocated),
                },
                unpredictable,
            })
        }
        0x200 => {
            // MRS (Banked register)
            // MRS{<c>}{<q>}  <Rd>, <banked_reg>
            let Rn: u8 = (bits & 0xf) as u8;
            let Rd: u8 = ((bits >> 12) & 0xf) as u8;
            let R: u8 = ((bits >> 22) & 0x1) as u8;
            let unpredictable: bool = Rn != 0b0000 || bits & 0xc00 != 0x0 || Rd == 15;
            let M1: u8 = ((bits >> 16) & 0xf) as u8;
            let M: u8 = ((bits >> 8) & 0x1) as u8;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::MrsBrA1As {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                banked_reg: {
                    if matches!(R << 5 | M << 4 | M1, 0x7 | 0xf | 0x18..=0x1b | 0x20..=0x2d | 0x2f | 0x31 | 0x33 | 0x35 | 0x37..=0x3b | 0x3d | 0x3f)
                    {
                        return Err(DecodeError::Unpredictable);
                    }
                    match BankedReg::from_bits(R << 5 | M << 4 | M1) {
                        Some(symbol) => symbol,
                        None => return Err(DecodeError::Unallocated),
                    }
                },
                unpredictable,
            })
        }
        0x200000 => {
            // MSR (register)
            // MSR{<c>}{<q>}  <spec_reg>, <Rn>
            let Rd: u8 = ((bits >> 12) & 0xf) as u8;
            let m: u8 = ((bits >> 8) & 0x1) as u8;
            let Rn: u8 = (bits & 0xf) as u8;
            let R: u8 = ((bits >> 22) & 0x1) as u8;
            let mask: u8 = ((bits >> 16) & 0xf) as u8;
            let unpredictable: bool =
                Rd != 0b1111 || m != 0b0 || bits & 0xc00 != 0x0 || mask == 0b0000 || Rn == 15;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::MsrRA1As {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                spec_reg: R << 4 | mask,
                Rn: GpReg::new(Rn),
                unpredictable,
            })
        }
        0x200200 => {
            // MSR (Banked register)
            // MSR{<c>}{<q>}  <banked_reg>, <Rn>
            let Rd: u8 = ((bits >> 12) & 0xf) as u8;
            let Rn: u8 = (bits & 0xf) as u8;
            let R: u8 = ((bits >> 22) & 0x1) as u8;
            let unpredictable: bool = Rd != 0b1111 || bits & 0xc00 != 0x0 || Rn == 15;
            let M1: u8 = ((bits >> 16) & 0xf) as u8;
            let M: u8 = ((bits >> 8) & 0x1) as u8;
            let cond: u8 = (bits >> 28) as u8;
            Ok(Instruction::MsrBrA1As {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                banked_reg: {
                    if matches!(R << 5 | M << 4 | M1, 0x7 | 0xf | 0x18..=0x1b | 0x20..=0x2d | 0x2f | 0x31 | 0x33 | 0x35 | 0x37..=0x3b | 0x3d | 0x3f)
                    {
                        return Err(DecodeError::Unpredictable);
                    }
                    match BankedReg::from_bits(R << 5 | M << 4 | M1) {
                        Some(symbol) => symbol,
                        None => return Err(DecodeError::Unallocated),
                    }
                },
                Rn: GpReg::new(Rn),
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

fn decode_movw(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xfb00000 != 0x3000000 {
        return Err(DecodeError::Unallocated);
    }
    // cond=xxxx|00|1|10|H=x|00|imm4=xxxx|Rd=xxxx|imm12=xxxxxxxxxxxx
    let Rd: u8 = ((bits >> 12) & 0xf) as u8;
    let imm4: u8 = ((bits >> 16) & 0xf) as u8;
    let imm12: u16 = (bits & 0xfff) as u16;
    let unpredictable: bool = Rd == 15;
    let cond: u8 = (bits >> 28) as u8;
    match bits & 0x400000 {
        0 => {
            // MOV, MOVS (immediate)
            // MOVW{<c>}{<q>}  <Rd>, #<imm16>
            Ok(Instruction::A2bMovIA2 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                imm16: (imm4 as u16) << 12 | imm12,
                unpredictable,
            })
        }
        0x400000 => {
            // MOVT
            // MOVT{<c>}{<q>}  <Rd>, #<imm16>
            Ok(Instruction::MovtA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                imm16: (imm4 as u16) << 12 | imm12,
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

